CALL {
  MATCH (e:Event) WHERE e.timestamp_utc >= '2025-12-08T00:00:00Z' AND e.timestamp_utc < '2025-12-09T00:00:00Z'
  WITH count(e) AS total_events
  MATCH (ch:CrowdHour) WHERE ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  WITH total_events, sum(ch.event_count) AS total_crowd_samples
  RETURN total_events + total_crowd_samples AS total_activity
}
CALL {
  MATCH (ch:CrowdHour) WHERE ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN avg(ch.avg_hc) AS avg_head_count, max(ch.peak_hc) AS peak_head_count
}
CALL {
  MATCH (e:Event) WHERE e.timestamp_utc >= '2025-12-08T00:00:00Z' AND e.timestamp_utc < '2025-12-09T00:00:00Z'
  RETURN e.event_type AS event_type, count(*) AS event_count
}
RETURN total_activity, avg_head_count, peak_head_count, event_type, event_count ORDER BY event_type
